class Solution { fun shortestPathAllKeys(grid:Array<String>):Int{val rows=grid.size;val columns=grid[0].length;var startRow=0;var startColumn=0;var target=0;for(r in 0 until rows)for(c in 0 until columns){val value=grid[r][c];if(value=='@'){startRow=r;startColumn=c}else if(value in 'a'..'f')target=target or (1 shl(value-'a'))};val seen=Array(rows){Array(columns){BooleanArray(64)}};val queue=java.util.ArrayDeque<IntArray>();queue.addLast(intArrayOf(startRow,startColumn,0,0));seen[startRow][startColumn][0]=true;val directions=intArrayOf(-1,0,1,0,-1);while(queue.isNotEmpty()){val state=queue.removeFirst();if(state[2]==target)return state[3];for(d in 0 until 4){val r=state[0]+directions[d];val c=state[1]+directions[d+1];if(r !in 0 until rows||c !in 0 until columns||grid[r][c]=='#')continue;val value=grid[r][c];var mask=state[2];if(value in 'A'..'F'&&(mask and (1 shl(value-'A')))==0)continue;if(value in 'a'..'f')mask=mask or (1 shl(value-'a'));if(!seen[r][c][mask]){seen[r][c][mask]=true;queue.addLast(intArrayOf(r,c,mask,state[3]+1))}}};return -1} }
